use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl Syn2MacroConverter { pub fn new (security : SecurityContext) -> Self { Self { security , bott_generator : None , } } # [doc = " Convert syn-based code to universal trait-based macro using Bott periodicity"] pub fn convert_syn_to_traits (& mut self , input : TokenStream) -> Result < TokenStream > { if ! self . security . check_permission (& AstOperation :: ParseItem) { return Err (anyhow :: anyhow ! ("Permission denied for ParseItem")) ; } self . bott_generator = Some (BottMacroGenerator :: new (input . clone ())) ; let item : Item = syn :: parse2 (input) ? ; let trait_impl = match item { Item :: Fn (func) => self . convert_function_to_trait (func) ? , Item :: Struct (struct_item) => self . convert_struct_to_trait (struct_item) ? , Item :: Enum (enum_item) => self . convert_enum_to_trait (enum_item) ? , Item :: Trait (trait_item) => self . convert_trait_to_universal (trait_item) ? , Item :: Impl (impl_item) => self . convert_impl_to_universal (impl_item) ? , _ => return Err (anyhow :: anyhow ! ("Unsupported item type")) , } ; if let Some (ref generator) = self . bott_generator { let bott_macros = generator . generate_all_levels () ; Ok (quote ! { # trait_impl pub mod bott_tower { use super ::*; # bott_macros } }) } else { Ok (trait_impl) } } fn convert_function_to_trait (& self , func : ItemFn) -> Result < TokenStream > { let func_name = & func . sig . ident ; let inputs = & func . sig . inputs ; let output = & func . sig . output ; let block = & func . block ; Ok (quote ! { pub trait # func_name { fn execute (# inputs) # output { # block } } impl < T : UniversalAst > # func_name for T { fn execute (# inputs) # output { if ! self . check_permission (& AstOperation :: TransformItem) { panic ! ("Permission denied") ; } self . sandbox_execute (|| { # block }) . unwrap () } } }) } fn convert_struct_to_trait (& self , struct_item : ItemStruct) -> Result < TokenStream > { let struct_name = & struct_item . ident ; let fields = & struct_item . fields ; Ok (quote ! { pub trait # struct_name { type Fields = # fields ; fn new (fields : Self :: Fields) -> Self ; fn fields (& self) -> & Self :: Fields ; } }) } fn convert_enum_to_trait (& self , enum_item : ItemEnum) -> Result < TokenStream > { let enum_name = & enum_item . ident ; let variants = & enum_item . variants ; Ok (quote ! { pub trait # enum_name { type Variants ; fn match_variant (& self) -> Self :: Variants ; } }) } fn convert_trait_to_universal (& self , trait_item : ItemTrait) -> Result < TokenStream > { let trait_name = & trait_item . ident ; let items = & trait_item . items ; Ok (quote ! { pub trait Universal # trait_name : UniversalAst + SecureExecution { # (# items) * } }) } fn convert_impl_to_universal (& self , impl_item : ItemImpl) -> Result < TokenStream > { let self_ty = & impl_item . self_ty ; let items = & impl_item . items ; Ok (quote ! { impl < T : UniversalAst + SecureExecution > UniversalImpl for # self_ty { # (# items) * } }) } }
}